insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '3b2303d6-7f96-577c-b73d-fd529f640d2e', e.id, 'LC', (select id from public.content_components where code = 'LC.TXT.CONT.FIL'), 'qa_passed', 'continuous', '{"title":"Porciones iguales","text":"Se suele decir que una decisión es justa cuando trata a todos por igual. Pero imaginemos un comedor escolar que sirve exactamente la misma porción a cada estudiante: al niño que no desayunó y al que ya comió dos veces. La igualdad de la porción no elimina la desigualdad del hambre; apenas la vuelve invisible. Quizá la justicia no consista en repartir lo mismo, sino en atender a lo que cada quien necesita para participar en condiciones parecidas.","svg":null,"table":null}'::jsonb, 'En el texto, la expresión «apenas la vuelve invisible» expresa la valoración de que el reparto idéntico', '[{"label":"A","text":"hace que el hambre desaparezca para quienes no desayunaron.","is_correct":false,"distractor_type":"Toma «invisible» como «inexistente».","explanation_feedback":"Incorrecta. Que algo se vuelva invisible no significa que desaparezca; el autor dice que la desigualdad sigue ahí, aunque no se note."},{"label":"B","text":"logra que todos los estudiantes terminen igual de satisfechos.","is_correct":false,"distractor_type":"Supone que porciones iguales producen resultados iguales, justo lo que el texto cuestiona.","explanation_feedback":"Incorrecta. El ejemplo muestra lo contrario: con la misma porción, quien no desayunó sigue con más hambre."},{"label":"C","text":"es la forma más justa de repartir, porque nadie recibe más que otro.","is_correct":false,"distractor_type":"Repite la opinión inicial que el autor presenta para luego discutirla.","explanation_feedback":"Incorrecta. Esa es la idea común con la que abre el texto («Se suele decir…»), y el autor la pone en duda."},{"label":"D","text":"oculta una diferencia real entre los estudiantes en lugar de corregirla.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Con «apenas», el autor valora negativamente el reparto idéntico: no elimina la desigualdad del hambre, solo impide verla."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
